import pyomo.environ as pyo

DATA = {
    "workers": ["I", "II", "III", "IV", "V"],
    "tasks": ["A", "B", "C", "D"],
    "time": {
        ("I", "A"): 9, ("I", "B"): 4, ("I", "C"): 3, ("I", "D"): 7,
        ("II", "A"): 4, ("II", "B"): 6, ("II", "C"): 5, ("II", "D"): 6,
        ("III", "A"): 5, ("III", "B"): 4, ("III", "C"): 7, ("III", "D"): 5,
        ("IV", "A"): 7, ("IV", "B"): 5, ("IV", "C"): 2, ("IV", "D"): 3,
        ("V", "A"): 10, ("V", "B"): 6, ("V", "C"): 7, ("V", "D"): 4,
    },
    "num_tasks": 4,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.W = pyo.Set(initialize=d["workers"])
    model.T = pyo.Set(initialize=d["tasks"])

    model.x = pyo.Var(model.W, model.T, within=pyo.Binary)

    def obj_rule(m):
        return sum(d["time"][(i, j)] * m.x[i, j] for i in m.W for j in m.T)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def task_rule(m, j):
        return sum(m.x[i, j] for i in m.W) == 1
    model.task_filled = pyo.Constraint(model.T, rule=task_rule)

    def worker_rule(m, i):
        return sum(m.x[i, j] for j in m.T) <= 1
    model.worker_at_most_one = pyo.Constraint(model.W, rule=worker_rule)

    return model
